using System;
using UnityEngine;

namespace RyanAssets.GameFeel {
    /// <summary>
    /// Maps every <see cref="FxKind"/> to its particle prefab and pool size. Generated by
    /// Ryan &gt; Game Feel &gt; Rebuild and referenced from <see cref="GameFeelSettings"/>.
    /// </summary>
    [CreateAssetMenu(menuName = "Ryan/Game Feel/Fx Library", fileName = "GameFxLibrary")]
    public sealed class GameFxLibrary : ScriptableObject {
        [Serializable]
        public sealed class Entry {
            public FxKind kind;
            [Tooltip("Root particle system; child systems play with it.")]
            public ParticleSystem prefab;
            [Tooltip("Instances kept ready. When all are busy the oldest one-shot is restarted.")]
            [Range(1, 32)] public int poolSize = 6;
        }

        [SerializeField] Entry[] entries = Array.Empty<Entry>();

        [Tooltip("A looping effect (beacon, trail) fired with GameFx.Play instead of Start stops emitting after this many seconds.")]
        [Min(0.1f)] public float loopingPlaySeconds = 2f;

        [NonSerialized] Entry[] byKind;

        public Entry[] Entries {
            get => entries;
            set { entries = value ?? Array.Empty<Entry>(); byKind = null; }
        }

        public Entry Get(FxKind kind) {
            if (byKind == null) {
                int max = 0;
                foreach (FxKind k in Enum.GetValues(typeof(FxKind)))
                    max = Mathf.Max(max, (int)k);
                byKind = new Entry[max + 1];
                foreach (Entry entry in entries)
                    if (entry != null && (int)entry.kind >= 0 && (int)entry.kind <= max && byKind[(int)entry.kind] == null)
                        byKind[(int)entry.kind] = entry;
            }
            int i = (int)kind;
            return i >= 0 && i < byKind.Length ? byKind[i] : null;
        }

        void OnValidate() => byKind = null;
    }
}
